func (v DataValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v DataValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v DataValue) String() string {
	return "DataValue"
}

func (v DataValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributeTypes := map[string]attr.Type{
		"created_at":            basetypes.StringType{},
		"deleted_at":            basetypes.StringType{},
		"display_name":          basetypes.StringType{},
		"email":                 basetypes.StringType{},
		"enabled":               basetypes.BoolType{},
		"first_name":            basetypes.StringType{},
		"id":                    basetypes.Int64Type{},
		"idms_id":               basetypes.Int64Type{},
		"last_login":            basetypes.StringType{},
		"last_name":             basetypes.StringType{},
		"password_needs_update": basetypes.BoolType{},
		"phone":                 basetypes.StringType{},
		"username":              basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"created_at":            v.CreatedAt,
			"deleted_at":            v.DeletedAt,
			"display_name":          v.DisplayName,
			"email":                 v.Email,
			"enabled":               v.Enabled,
			"first_name":            v.FirstName,
			"id":                    v.Id,
			"idms_id":               v.IdmsId,
			"last_login":            v.LastLogin,
			"last_name":             v.LastName,
			"password_needs_update": v.PasswordNeedsUpdate,
			"phone":                 v.Phone,
			"username":              v.Username,
		})

	return objVal, diags
}

func (v DataValue) Equal(o attr.Value) bool {
	other, ok := o.(DataValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.CreatedAt.Equal(other.CreatedAt) {
		return false
	}

	if !v.DeletedAt.Equal(other.DeletedAt) {
		return false
	}

	if !v.DisplayName.Equal(other.DisplayName) {
		return false
	}

	if !v.Email.Equal(other.Email) {
		return false
	}

	if !v.Enabled.Equal(other.Enabled) {
		return false
	}

	if !v.FirstName.Equal(other.FirstName) {
		return false
	}

	if !v.Id.Equal(other.Id) {
		return false
	}

	if !v.IdmsId.Equal(other.IdmsId) {
		return false
	}

	if !v.LastLogin.Equal(other.LastLogin) {
		return false
	}

	if !v.LastName.Equal(other.LastName) {
		return false
	}

	if !v.PasswordNeedsUpdate.Equal(other.PasswordNeedsUpdate) {
		return false
	}

	if !v.Phone.Equal(other.Phone) {
		return false
	}

	if !v.Username.Equal(other.Username) {
		return false
	}

	return true
}

func (v DataValue) Type(ctx context.Context) attr.Type {
	return DataType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

